const items = $input.all();

const dateData = {};

for (const item of items) {
  if (!item || !item.json) continue;

  const row = item.json;

  let date = String(row.date || "").trim();

  if (!date) continue;

  // ISO date ko YYYY-MM-DD mein convert karo
  if (date.includes("T")) {
    date = date.split("T")[0];
  }

  // DD-MM-YYYY ko YYYY-MM-DD mein convert karo
  if (/^\d{2}-\d{2}-\d{4}$/.test(date)) {
    const parts = date.split("-");
    date = `${parts[2]}-${parts[1]}-${parts[0]}`;
  }

  // Basic date validation
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    continue;
  }

  if (!dateData[date]) {
    dateData[date] = {
      date: date,
      count: 0
    };
  }

  dateData[date].count += 1;
}

// Date ke according ascending order
const result = Object.values(dateData)
  .sort((a, b) => a.date.localeCompare(b.date));

return result.map(item => ({
  json: item
}));

const items = $input.all();

const data = {};

for (const item of items) {
  if (!item || !item.json) continue;

  const row = item.json;

  const state = String(row.edition_state || "")
    .trim()
    .toLowerCase();

  const department = String(row.department || "")
    .trim()
    .toLowerCase();

  if (!state || !department) continue;

  // State create karo
  if (!data[state]) {
    data[state] = {
      state: state
    };
  }

  // Department dynamically add karo
  if (!data[state][department]) {
    data[state][department] = 0;
  }

  data[state][department] += 1;
}

// Output ko n8n items mein convert karo
const result = Object.values(data);

// State-wise total bhi calculate karo
for (const item of result) {
  let total = 0;

  for (const key of Object.keys(item)) {
    if (key !== "state" && typeof item[key] === "number") {
      total += item[key];
    }
  }

  item.total = total;
}

// Highest total wale states pehle
result.sort((a, b) => b.total - a.total);

return result.map(item => ({
  json: item
}));

