const items = $input.all();

let totalRecords = 0;
let validRecords = 0;
let invalidRecords = 0;
let duplicateRecords = 0;

const states = new Set();
const departments = new Set();
const designations = new Set();

let latestDate = null;

// Required fields
const requiredFields = [
  "full_name",
  "email",
  "date",
  "edition_state",
  "department"
];

let completeRecords = 0;

for (const item of items) {
  if (!item || !item.json) continue;

  const row = item.json;

  totalRecords++;

  // -------------------------
  // Validation
  // -------------------------
  const validationStatus = String(
    row.validation_status || ""
  ).trim().toLowerCase();

  if (validationStatus === "valid") {
    validRecords++;
  }

  if (validationStatus === "invalid") {
    invalidRecords++;
  }

  // -------------------------
  // Duplicate
  // -------------------------
  const isDuplicate =
    row.is_duplicate === true ||
    String(row.is_duplicate || "").toLowerCase() === "true";

  if (isDuplicate) {
    duplicateRecords++;
  }

  // -------------------------
  // States
  // -------------------------
  const state = String(row.edition_state || "")
    .trim()
    .toLowerCase();

  if (state) {
    states.add(state);
  }

  // -------------------------
  // Departments
  // -------------------------
  const department = String(row.department || "")
    .trim()
    .toLowerCase();

  if (department) {
    departments.add(department);
  }

  // -------------------------
  // Designations
  // -------------------------
  const designation = String(row.designation || "")
    .trim()
    .toLowerCase();

  if (designation) {
    designations.add(designation);
  }

  // -------------------------
  // Latest Date
  // -------------------------
  let date = String(row.date || "").trim();

  if (date.includes("T")) {
    date = date.split("T")[0];
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    if (!latestDate || date > latestDate) {
      latestDate = date;
    }
  }

  // -------------------------
  // Data Completeness
  // -------------------------
  let complete = true;

  for (const field of requiredFields) {
    const value = String(row[field] || "").trim();

    if (!value) {
      complete = false;
      break;
    }
  }

  if (complete) {
    completeRecords++;
  }
}

// -------------------------
// Calculations
// -------------------------

const completenessPercentage =
  totalRecords > 0
    ? Number(((completeRecords / totalRecords) * 100).toFixed(2))
    : 0;

const validPercentage =
  totalRecords > 0
    ? Number(((validRecords / totalRecords) * 100).toFixed(2))
    : 0;

// -------------------------
// Final KPI Object
// -------------------------

return [
  {
    json: {
      total_records: totalRecords,

      total_states: states.size,

      total_departments: departments.size,

      total_designations: designations.size,

      valid_records: validRecords,

      invalid_records: invalidRecords,

      duplicate_records: duplicateRecords,

      active_states: states.size,

      latest_submission: latestDate || "N/A",

      complete_records: completeRecords,

      data_completeness_percentage: completenessPercentage,

      valid_percentage: validPercentage
    }
  }
];

