const items = $input.all();

const dashboard = {
  kpis: {},
  stateMap: [],
  stateRanking: [],
  departments: [],
  dateTrend: [],
  stateDepartment: [],
  designations: [],
  validation: []
};

for (const item of items) {
  if (!item || !item.json) continue;

  const row = item.json;

  // -------------------------
  // KPI
  // -------------------------
  if (
    row.total_records !== undefined ||
    row.total_states !== undefined ||
    row.total_departments !== undefined
  ) {
    dashboard.kpis = row;
    continue;
  }

  // -------------------------
  // Department Distribution
  // -------------------------
  if (
    row.department !== undefined &&
    row.count !== undefined &&
    row.percentage !== undefined
  ) {
    dashboard.departments.push(row);
    continue;
  }

  // -------------------------
  // Validation
  // -------------------------
  if (
    row.status !== undefined &&
    row.count !== undefined
  ) {
    dashboard.validation.push(row);
    continue;
  }

  // -------------------------
  // Designation Distribution
  // -------------------------
  if (
    row.designation !== undefined &&
    row.count !== undefined
  ) {
    dashboard.designations.push(row);
    continue;
  }

  // -------------------------
  // Date Trend
  // -------------------------
  if (
    row.date !== undefined &&
    row.count !== undefined
  ) {
    dashboard.dateTrend.push(row);
    continue;
  }

  // -------------------------
  // State Map
  // -------------------------
  if (
    row.state !== undefined &&
    row.display_state !== undefined &&
    row.state_code !== undefined
  ) {
    dashboard.stateMap.push(row);
    continue;
  }

  // -------------------------
  // State × Department
  // -------------------------
  if (
    row.state !== undefined &&
    row.total !== undefined
  ) {
    dashboard.stateDepartment.push(row);
    continue;
  }

  // -------------------------
  // State Ranking
  // -------------------------
  if (
    row.state !== undefined &&
    row.count !== undefined
  ) {
    dashboard.stateRanking.push(row);
    continue;
  }
}

// Sorting

dashboard.stateMap.sort((a, b) => b.count - a.count);

dashboard.stateRanking.sort((a, b) => b.count - a.count);

dashboard.departments.sort((a, b) => b.count - a.count);

dashboard.designations.sort((a, b) => b.count - a.count);

dashboard.dateTrend.sort((a, b) =>
  String(a.date).localeCompare(String(b.date))
);

return [
  {
    json: dashboard
  }
];

