  <div class="card">

    <h2>Department Distribution</h2>

    <p>Records by department</p>

    <div class="chart-container">

      <canvas id="departmentChart"></canvas>

    </div>

  </div>

</div>


<!-- ================= DATE + STATE ================= -->

<div class="grid-equal">

  <div class="card">

    <h2>Entries Over Time</h2>

    <p>Daily record submission trend</p>

    <div class="chart-container">

      <canvas id="dateChart"></canvas>

    </div>

  </div>


  <div class="card">

    <h2>State-wise Records</h2>

    <p>Number of records by state</p>

    <div class="chart-container">

      <canvas id="stateChart"></canvas>

    </div>

  </div>

</div>


<!-- ================= STATE DEPARTMENT ================= -->

<div class="card" style="margin-bottom:20px">

  <h2>State × Department Analysis</h2>

  <p>
    Department-wise distribution across states
  </p>

  <div class="chart-container">

    <canvas id="stateDepartmentChart"></canvas>

  </div>

</div>


<!-- ================= VALIDATION + DESIGNATION ================= -->

<div class="grid-equal">

  <div class="card">

    <h2>Data Validation</h2>

    <p>
      Valid and invalid records
    </p>

    <div class="chart-container">

      <canvas id="validationChart"></canvas>

    </div>

  </div>


  <div class="card">

    <h2>Designation Distribution</h2>

    <p>
      Current designation coverage
    </p>

    <div class="chart-container">

      <canvas id="designationChart"></canvas>

    </div>

  </div>

</div>

</div>


<script>

// =======================================
// DATA FROM N8N
// =======================================

const stateData = ${json(stateMap)};

const stateRanking = ${json(stateRanking)};

const departmentData = ${json(departments)};

const dateData = ${json(dateTrend)};

const stateDepartmentData = ${json(stateDepartment)};

const designationData = ${json(designations)};

const validationData = ${json(validation)};


// =======================================
// INDIA MAP
// =======================================

const map = L.map('indiaMap', {

  zoomControl: true,

  minZoom: 4,

  maxZoom: 8

}).setView([22.5, 80], 4.5);


// No tile layer.
// State GeoJSON itself will create the map.

// State count lookup
const stateLookup = {};

stateData.forEach(s => {

  const key = String(
    s.state || ''
  ).trim().toLowerCase();

  stateLookup[key] = s;

});


// Color scale
function getColor(count) {

  if (!count) return '#e5e7eb';

  if (count >= 20) return '#08306b';

  if (count >= 10) return '#2171b5';

  if (count >= 5) return '#4292c6';

  if (count >= 2) return '#6baed6';

  return '#c6dbef';

}


// State name normalization
function normalizeState(name) {

  return String(name || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/\\s+/g, ' ');

}


// GeoJSON style
function style(feature) {

  const props = feature.properties || {};

  const possibleNames = [

    props.name,
    props.NAME_1,
    props.st_nm,
    props.ST_NM,
    props.state,
    props.State

  ];

  let name = '';

  for (const n of possibleNames) {

    if (n) {

      name = normalizeState(n);

      break;

    }

  }

  const data = stateLookup[name];

  const count = data ? Number(data.count || 0) : 0;

  return {

    fillColor: getColor(count),

    weight: 1,

    opacity: 1,

    color: '#ffffff',

    fillOpacity: 0.85

  };

}


// Feature interactions
function onEachFeature(feature, layer) {

  const props = feature.properties || {};

  let name = '';

  const possibleNames = [

    props.name,
    props.NAME_1,
    props.st_nm,
    props.ST_NM,
    props.state,
    props.State

  ];

  for (const n of possibleNames) {

    if (n) {

      name = n;

      break;

    }

  }

  const normalized = normalizeState(name);

  const data = stateLookup[normalized];

  const count = data
    ? Number(data.count || 0)
    : 0;

  const percentage = data
    ? Number(data.percentage || 0)
    : 0;


  layer.bindTooltip(

    '<b>' +
    (name || 'State') +
    '</b><br>' +
    'Records: ' +
    count +
    '<br>' +
    'Share: ' +
    percentage +
    '%',

    {
      sticky: true
    }

  );


  layer.on({

    mouseover: function(e) {

      e.target.setStyle({

        weight: 3,

        color: '#111827',

        fillOpacity: 0.95

      });

    },

    mouseout: function(e) {

      e.target.setStyle(style(feature));

    },

    click: function() {

      const selected = data || {

        display_state: name,

        count: 0,

        percentage: 0

      };

      alert(

        selected.display_state +
        '\\n\\nRecords: ' +
        selected.count +
        '\\nPercentage: ' +
        selected.percentage +
        '%'

      );

    }

  });

}


// Load India GeoJSON
fetch(
  'https://cdn.jsdelivr.net/gh/udit-001/india-maps-data@main/geojson/india.geojson'
)

.then(response => response.json())

.then(geojson => {

  L.geoJSON(

    geojson,

    {

      style: style,

      onEachFeature: onEachFeature

    }

  ).addTo(map);

})

.catch(error => {

  console.error(
    'India GeoJSON loading error:',
    error
  );

});


// =======================================
// DEPARTMENT CHART
// =======================================

new Chart(

  document.getElementById(
    'departmentChart'
  ),

  {

    type: 'doughnut',

    data: {

      labels: departmentData.map(
        x => x.department
      ),

      datasets: [{

        data: departmentData.map(
          x => Number(x.count || 0)
        )

      }]

    },

    options: {

      responsive: true,

      maintainAspectRatio: false,

      plugins: {

        legend: {

          position: 'bottom'

        }

      }

    }

  }

);


// =======================================
// DATE TREND
// =======================================

new Chart(

  document.getElementById(
    'dateChart'
  ),

  {

    type: 'line',

    data: {

      labels: dateData.map(
        x => x.date
      ),

      datasets: [{

        label: 'Records',

        data: dateData.map(
          x => Number(x.count || 0)
        ),

        tension: 0.3,

        fill: false

      }]

    },

    options: {

      responsive: true,

      maintainAspectRatio: false,

      plugins: {

        legend: {

          display: false

        }

      }

    }

  }

);


// =======================================
// STATE RANKING
// =======================================

new Chart(

  document.getElementById(
    'stateChart'
  ),

  {

    type: 'bar',

    data: {

      labels: stateRanking.map(
        x =>
          x.display_state ||
          x.state
      ),

      datasets: [{

        label: 'Records',

        data: stateRanking.map(
          x => Number(x.count || 0)
        )

      }]

    },

    options: {

      responsive: true,

      maintainAspectRatio: false,

      indexAxis: 'y',

      plugins: {

        legend: {

          display: false

        }

      }

    }

  }

);


// =======================================
// STATE × DEPARTMENT
// =======================================

const states = [
  ...new Set(
    stateDepartmentData.map(
      x => x.state
    )
  )
];

const departments = [
  ...new Set(
    stateDepartmentData.flatMap(
      x =>
        Object.keys(x).filter(
          key =>
            key !== 'state' &&
            key !== 'total'
        )
    )
  )
];


new Chart(

  document.getElementById(
    'stateDepartmentChart'
  ),

  {

    type: 'bar',

    data: {

      labels: states,

      datasets: departments.map(
        dept => ({

          label: dept,

          data: states.map(
            state => {

              const row =
                stateDepartmentData.find(
                  x =>
                    x.state === state
                );

              return row
                ? Number(row[dept] || 0)
                : 0;

            }

          )

        })
      )

    },

    options: {

      responsive: true,

      maintainAspectRatio: false,

      scales: {

        x: {

          stacked: true

        },

        y: {

          stacked: true,

          beginAtZero: true

        }

      }

    }

  }

);


// =======================================
// VALIDATION
// =======================================

const validationFiltered =
  validationData.filter(
    x =>
      x.status === 'valid' ||
      x.status === 'invalid'
  );


new Chart(

  document.getElementById(
    'validationChart'
  ),

  {

    type: 'doughnut',

    data: {

      labels:
        validationFiltered.map(
          x => x.status
        ),

      datasets: [{

        data:
          validationFiltered.map(
            x => Number(x.count || 0)
          )

      }]

    },

    options: {

      responsive: true,

      maintainAspectRatio: false,

      plugins: {

        legend: {

          position: 'bottom'

        }

      }

    }

  }

);


// =======================================
// DESIGNATION
// =======================================

new Chart(

  document.getElementById(
    'designationChart'
  ),

  {

    type: 'bar',

    data: {

      labels:
        designationData.map(
          x => x.designation
        ),

      datasets: [{

        label: 'Records',

        data:
          designationData.map(
            x => Number(x.count || 0)
          )

      }]

    },

    options: {

      responsive: true,

      maintainAspectRatio: false,

      plugins: {

        legend: {

          display: false

        }

      }

    }

  }

);

</script>

</body>

</html>`;

// Return HTML
return [
  {
    json: {
      html: html
    }
  }
];
